class Solution {
  private static final long MASK = (1L << 30) - 1;
  private final java.util.TreeSet<Long> top = new java.util.TreeSet<>();
  private final java.util.TreeSet<Long> rest = new java.util.TreeSet<>();
  private long sum;
  private int x;

  private static long val(long key) {
    return (key >> 30) * (key & MASK);
  }

  private void add(long key) {
    if (top.size() < x) {
      top.add(key);
      sum += val(key);
    } else if (key > top.first()) {
      long low = top.pollFirst();
      sum -= val(low);
      rest.add(low);
      top.add(key);
      sum += val(key);
    } else rest.add(key);
  }

  private void remove(long key) {
    if (top.remove(key)) {
      sum -= val(key);
      if (!rest.isEmpty()) {
        long up = rest.pollLast();
        top.add(up);
        sum += val(up);
      }
    } else rest.remove(key);
  }

  public long[] findXSum(int[] nums, int k, int x) {
    this.x = x;
    int n = nums.length;
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    long[] ans = new long[n - k + 1];
    for (int i = 0; i < n; i++) {
      for (int step = 0; step < 2; step++) {
        int idx = step == 0 ? i : i - k;
        if (idx < 0) continue;
        int v = nums[idx];
        int f = freq.getOrDefault(v, 0);
        if (f > 0) remove(((long) f << 30) | v);
        f += step == 0 ? 1 : -1;
        freq.put(v, f);
        if (f > 0) add(((long) f << 30) | v);
      }
      if (i >= k - 1) ans[i - k + 1] = sum;
    }
    return ans;
  }
}
